import React, { useState } from 'react';
import API from '../api';

const BUSINESS_TYPES = [
  'Tech startups (apps, software, IT services)', 'E-commerce businesses',
  'Restaurants and cafes', 'Private schools (KG–Grade 12)',
  'Advertising and marketing agencies', 'Retail shops and minimarkets',
  'Medical clinics and pharmacies', 'Construction companies',
  'Transportation and logistics services', 'Beauty salons and barber shops',
  'Other',
];

export default function Contact() {
  const [form, setForm] = useState({ full_name: '', email: '', phone: '', business_type: '', company_name: '', tin_number: '', elmis_registration: '', business_license: '', message: '' });
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await API.post('/contact', form);
      setSubmitted(true);
    } catch {
      alert('Submission failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 700, margin: '0 auto', padding: '60px 24px' }}>
      <h1 style={{ fontSize: 40, fontWeight: 900, marginBottom: 8 }}>Contact Us</h1>
      <p style={{ color: '#a3a3a3', marginBottom: 40 }}>Ready to grow your business?</p>

      {/* Contact info */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 40 }}>
        {[
          ['📧', 'Email', 'allthingsethiopia2026@gmail.com'],
          ['📍', 'Location', 'Addis Ababa, Ethiopia'],
          ['🕐', 'Hours', 'Mon–Fri: 9AM–6PM'],
          ['✈️', 'Telegram', '@Allthings2026'],
        ].map(([icon, label, val]) => (
          <div key={label} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 14, padding: 16, display: 'flex', alignItems: 'center', gap: 12 }}>
            <span style={{ fontSize: 22 }}>{icon}</span>
            <div>
              <div style={{ fontWeight: 600, fontSize: 14 }}>{label}</div>
              <div style={{ color: '#a3a3a3', fontSize: 13 }}>{val}</div>
            </div>
          </div>
        ))}
      </div>

      {submitted ? (
        <div style={{ background: '#22c55e15', border: '1px solid #22c55e40', borderRadius: 16, padding: 40, textAlign: 'center' }}>
          <div style={{ fontSize: 56, marginBottom: 16 }}>✅</div>
          <h3 style={{ fontSize: 22, fontWeight: 800, marginBottom: 8 }}>Message Sent!</h3>
          <p style={{ color: '#a3a3a3' }}>Thank you! We will contact you soon.</p>
          <button onClick={() => setSubmitted(false)} style={{ marginTop: 20, background: 'none', border: '1px solid #333', color: '#fff', padding: '10px 20px', borderRadius: 8, cursor: 'pointer' }}>
            Send Another
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 20, padding: 32 }}>
          <h3 style={{ fontSize: 18, fontWeight: 700, marginBottom: 24 }}>Send Us a Message</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
            <Field label="Full Name *" name="full_name" value={form.full_name} onChange={handleChange} required />
            <Field label="Email" name="email" type="email" value={form.email} onChange={handleChange} />
            <Field label="Phone *" name="phone" value={form.phone} onChange={handleChange} required />
            <Field label="Company Name" name="company_name" value={form.company_name} onChange={handleChange} />
            <Field label="TIN Number" name="tin_number" value={form.tin_number} onChange={handleChange} />
            <Field label="E-LMIS Registration" name="elmis_registration" value={form.elmis_registration} onChange={handleChange} />
            <Field label="Business License" name="business_license" value={form.business_license} onChange={handleChange} />
          </div>
          <div style={{ marginBottom: 14 }}>
            <label style={labelStyle}>Business Type</label>
            <select name="business_type" value={form.business_type} onChange={handleChange} style={inputStyle}>
              <option value="">Select...</option>
              {BUSINESS_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <div style={{ marginBottom: 24 }}>
            <label style={labelStyle}>Message</label>
            <textarea name="message" value={form.message} onChange={handleChange} rows={4} style={{ ...inputStyle, resize: 'vertical' }} placeholder="Tell us about your business..." />
          </div>
          <div style={{ background: '#f9731610', border: '1px solid #f9731630', borderRadius: 10, padding: 12, marginBottom: 20, fontSize: 13, color: '#a3a3a3' }}>
            📋 Important: We only work with licensed businesses.
          </div>
          <button type="submit" disabled={loading} style={{ width: '100%', padding: 14, background: '#f97316', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, fontSize: 16 }}>
            {loading ? 'Submitting...' : 'Submit Application →'}
          </button>
        </form>
      )}
    </div>
  );
}

const Field = ({ label, name, type = 'text', value, onChange, required }) => (
  <div style={{ marginBottom: 14 }}>
    <label style={labelStyle}>{label}</label>
    <input type={type} name={name} value={value} onChange={onChange} required={required} style={inputStyle} />
  </div>
);

const inputStyle = { width: '100%', padding: '10px 12px', background: '#0a0a0a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: 14 };
const labelStyle = { display: 'block', fontSize: 13, color: '#a3a3a3', marginBottom: 6 };
